using System.Security.Cryptography;
using System.Text;
using Dapper;
using Npgsql;
using ShipLean.Contracts.Search;

namespace ShipLean.TestSupport.Builders;

// Arranges one search_doc row with parameterised SQL and returns its id, without the indexer. Defaults: chunk 0, no work item,
// not embedded, text_hash the SHA-256 hex of the text, indexed now. The tsv column is generated by the database.
// project_id and work_item_id are foreign keys: the project must exist, and item, comment and attachment rows need a real work item
// (WithWorkItem), so arrange them with WorkItemBuilder, never Guid.NewGuid().
public sealed class SearchDocBuilder(Guid projectId, SearchSourceKind kind, Guid sourceId, SearchField field, string text)
{
    private Guid _id = Guid.NewGuid();
    private Guid? _workItemId;
    private int _chunkNo;
    private string? _textHash;
    private float[]? _embedding;
    private string? _embeddingModel;
    private DateTimeOffset? _indexedAt;

    public SearchDocBuilder WithId(Guid id)
    {
        _id = id;
        return this;
    }

    public SearchDocBuilder WithWorkItem(Guid workItemId)
    {
        _workItemId = workItemId;
        return this;
    }

    public SearchDocBuilder WithChunk(int chunkNo)
    {
        _chunkNo = chunkNo;
        return this;
    }

    public SearchDocBuilder WithTextHash(string textHash)
    {
        _textHash = textHash;
        return this;
    }

    public SearchDocBuilder WithEmbedding(float[] embedding, EmbeddingModelId model)
    {
        _embedding = embedding;
        _embeddingModel = model.ToString();
        return this;
    }

    public SearchDocBuilder WithIndexedAt(DateTimeOffset indexedAt)
    {
        _indexedAt = indexedAt;
        return this;
    }

    public static string HashOf(string text) => Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(text)));

    public async Task<Guid> InsertAsync(NpgsqlConnection connection)
    {
        await connection.ExecuteAsync(
            """
            INSERT INTO search_doc (id, project_id, source_kind, source_id, work_item_id, chunk_no, field, text, text_hash, embedding, embedding_model, indexed_at)
            VALUES (@id, @projectId, @kind, @sourceId, @workItemId::uuid, @chunkNo, @field, @text, @textHash, @embedding::real[], @embeddingModel, coalesce(@indexedAt::timestamptz, now()))
            """,
            new
            {
                id = _id,
                projectId,
                kind = SearchDocColumns.Kind(kind),
                sourceId,
                workItemId = _workItemId,
                chunkNo = _chunkNo,
                field = SearchDocColumns.Field(field),
                text,
                textHash = _textHash ?? HashOf(text),
                embedding = _embedding,
                embeddingModel = _embeddingModel,
                indexedAt = _indexedAt?.ToUniversalTime(),
            });
        return _id;
    }
}
